-- BeeAware Brasil roadmap — SinespAdapter's real data, populated manually.
--
-- sinesp.ts (adapter logic) has been fully built and correct for a while
-- — real bulk-download URL found, real per-row parsing verified locally —
-- but was never registered in ingest-security-sources/index.ts because
-- fetch() genuinely cannot complete inside the Edge Function's execution
-- window: the source file (bancovde-{year}.xlsx, ~20MB, an old Zope/Plone
-- server behind Varnish) has a measured ~14-16s floor from Supabase's own
-- sa-east-1 region, confirmed across three separate mitigation attempts
-- (default region, region-pinning, chunked/parallel/sequential download —
-- see sinesp.ts's own header for the full diagnostic trail). That header
-- names the fix directly: "moving this specific download outside the Edge
-- Function's own execution window entirely... by whatever means."
--
-- This migration is that means, for this one population: downloaded and
-- parsed bancovde-2026.xlsx from a normal (non-Edge-Function) machine —
-- no such timing ceiling there, the same GET that fails from Supabase's
-- infrastructure completed in seconds — reproducing sinesp.ts's exact
-- normalize() logic (same EVENTO_MAP, same IBGE-municipality accent-
-- insensitive resolution, same "Estadual" scope, same trailing-2-month
-- window, same dedupe-by-source_record_id) in a local script, verified
-- against the real file: 485,175 rows scanned, 3,401 real events survive
-- every filter (occurrence_count > 0, municipality resolved against
-- IBGE's national list — only 29 rows failed to resolve, and all 29 were
-- the literal "NÃO INFORMADO" placeholder, not a real unmatched name).
--
-- This is a one-off population, not a substitute for a real recurring
-- schedule — SinespAdapter is still NOT registered in
-- ingest-security-sources/index.ts, since a scheduled run there would
-- still fail the same way. Re-running this (or building a real external
-- trigger, per sinesp.ts's own suggested fix) is how this data would stay
-- current; it will not auto-refresh on its own.
insert into security_sources (
  country_code, state_code, name, organisation, source_type, source_url,
  adapter_name, adapter_version, refresh_frequency,
  last_check, last_success, last_data_date, active
) values (
  'BR', null,
  'SINESP VDE - Base de Dados Nacional',
  'Ministério da Justiça e Segurança Pública',
  'official',
  'https://www.gov.br/mj/pt-br/assuntos/sua-seguranca/seguranca-publica/estatistica/dados-nacionais-1/base-de-dados-e-notas-metodologicas-dos-gestores-estaduais-sinesp-vde-2022-e-2023',
  'SinespAdapter', '1.0.0', 'monthly',
  now(), now(), '2026-08-01', true
)
on conflict (adapter_name) do update set
  last_check = excluded.last_check,
  last_success = excluded.last_success,
  last_data_date = excluded.last_data_date;

insert into security_events (
  country_code, state_code, city_ibge_code, source_id, source_record_id,
  source_type, event_category, event_type, original_category, occurred_at,
  geo_precision, location_confidence, city, state, occurrence_count,
  victim_count, severity, confidence_score
)
select
  'BR', v.state_code, v.city_ibge_code,
  (select id from security_sources where adapter_name = 'SinespAdapter'),
  v.source_record_id, 'official', v.event_category::security_event_category, v.event_type,
  v.original_category, v.occurred_at::timestamptz, 'MUNICIPALITY'::geo_precision, 0.5,
  v.city, v.state, v.occurrence_count::integer, v.victim_count::integer, v.severity,
  v.confidence_score::numeric
